  @override
  String get legalDisclaimerAINotLawyerBody =>
      'અમ્બ્રેલાની AI સિસ્ટમ્સ સામાન્ય કાનૂની કોર્પોરા પર પ્રશિક્ષિત મોટા ભાષાના મોડલ છે. તેઓ પ્રેક્ટિસિંગ સર્ટિફિકેટ ધરાવતા નથી, કોર્ટમાં હાજર થઈ શકતા નથી, કોઈપણ બાર એસોસિએશન અથવા લૉ સોસાયટી દ્વારા નિયંત્રિત નથી અને વકીલ તરીકે તમારી સંભાળ રાખવાની કોઈ ફરજ નથી. AI આઉટપુટમાં: હકીકતલક્ષી ભૂલો અથવા આભાસ હોઈ શકે છે; તમારા ચોક્કસ તથ્યો સાથે સંબંધિત સામગ્રી વિચારણાઓને છોડી દો; કાયદાઓ અથવા કેસોને ટાંકવા કે જેમાં સુધારો કરવામાં આવ્યો છે, રદ કરવામાં આવ્યો છે અથવા રદ કરવામાં આવ્યો છે; તાજેતરના કાયદાકીય ફેરફારોને ધ્યાનમાં લેવામાં નિષ્ફળ; અને જટિલ અથવા અસ્પષ્ટ કાનૂની પ્રશ્નોનું ખોટું અર્થઘટન કરે છે. તમારે દરેક AI આઉટપુટને પૂછપરછ માટે પ્રારંભિક બિંદુ તરીકે ગણવું જોઈએ, અંતિમ જવાબ નહીં.';

