  @override
  String get legalDisclaimerJurisdictionBody =>
      'ભારત: AI વિશ્લેષણ કેન્દ્રીય કાયદા, રાજ્યના કૃત્યો જ્યાં ઉલ્લેખિત છે અને પ્રકાશિત ન્યાયિક નિર્ણયો પર આધારિત છે. તે જિલ્લા કોર્ટ-સ્તરની પ્રેક્ટિસ, સ્થાનિક બાર રિવાજો, અથવા બિનકોડીકૃત પ્રક્રિયાત્મક નિયમો માટે જવાબદાર નથી. યુનાઇટેડ સ્ટેટ્સ: AI વિશ્લેષણ ફેડરલ કાયદા અને પસંદગીના રાજ્ય કાયદા પર આધારિત છે. યુએસ કાનૂની વિશ્લેષણ એ રાજ્ય-વિશિષ્ટ લાઇસન્સ પ્રાપ્ત સલાહકારનો વિકલ્પ નથી. ચકાસાયેલ વકીલની સમીક્ષા વિના ઇમિગ્રેશન, ફોજદારી બચાવ અથવા કર બાબતો માટે ઉપલબ્ધ નથી. કેન્યા: કેન્યાના કાયદાઓ, પેટાકંપની કાયદાઓ અને પ્રકાશિત હાઇકોર્ટ અને અપીલના નિર્ણયો પર વિશ્લેષણ દોરે છે. તે રૂઢિગત કાયદો, મેજિસ્ટ્રેટ કોર્ટની વિવિધતાઓ અથવા અપ્રકાશિત ચુકાદાઓને ધ્યાનમાં લેતું નથી. યુનાઇટેડ કિંગડમ: વિશ્લેષણ અંગ્રેજી અને વેલ્શ કાયદાને આવરી લે છે. સ્કોટ્સ કાયદો, ઉત્તરી આઇરિશ કાયદો, અને વિકૃત બાબતો નોંધપાત્ર રીતે અલગ હોઈ શકે છે; અધિકારક્ષેત્ર-વિશિષ્ટ સલાહ લેવી.';

