      'Umbrella\'s AI સાથેના સંચાર કોઈપણ અધિકારક્ષેત્રમાં એટર્ની-ક્લાયન્ટ વિશેષાધિકાર અથવા કાનૂની વ્યાવસાયિક વિશેષાધિકાર દ્વારા સુરક્ષિત નથી. તમે વિશેષાધિકાર હેઠળ રક્ષણ કરવા માંગતા હો તે પ્લેટફોર્મ પર માહિતી સબમિટ કરશો નહીં. જો તમે અમ્બ્રેલા માર્કેટપ્લેસ દ્વારા લાઇસન્સ પ્રાપ્ત વકીલને જોડો છો, તો વિશેષાધિકાર એ વકીલ સાથેના તમારા સંચારને એક્ઝિક્યુટેડ રીટેનર એગ્રીમેન્ટ હેઠળ જોડી શકે છે, પરંતુ તમારી અગાઉની AI ક્રિયાપ્રતિક્રિયાઓ સાથે નહીં.';

