      'DVTech Ventures એ ટેક્નોલોજી કંપની છે, નિયમન કરેલ કાનૂની સેવા પ્રદાતા નથી. અમે સોલિસિટર રેગ્યુલેશન ઓથોરિટી (યુકે), બાર કાઉન્સિલ ઓફ ઈન્ડિયા, કેન્યાની લો સોસાયટી, કોઈપણ યુએસ સ્ટેટ બાર, અથવા કોઈપણ અન્ય કાનૂની નિયમનકારી સંસ્થા દ્વારા કાનૂની સેવાઓ પ્રદાન કરવા માટે અધિકૃત નથી. અમ્બ્રેલા પ્લેટફોર્મ કાનૂની સેવા અધિનિયમ 2007 (યુકે) અથવા અન્ય અધિકારક્ષેત્રોમાં સમકક્ષ કાયદામાં વ્યાખ્યાયિત કર્યા મુજબ નિયંત્રિત કાનૂની પ્રવૃત્તિ પ્રદાન કરતું નથી.';

