  @override
  String get legalPrivacyAutomatedBody =>
      'અમ્બ્રેલા કાનૂની વિશ્લેષણ જનરેટ કરવા, સમસ્યાઓ ઓળખવા અને પગલાં સૂચવવા માટે AI નો ઉપયોગ કરે છે. આ AI આઉટપુટ માત્ર માહિતીપ્રદ છે અને તમારા કાનૂની અધિકારો વિશે બંધનકર્તા નિર્ણયો નથી બનાવતા. માનવીય સમીક્ષા વિના તમારા વિશે કાનૂની અથવા સમાન નોંધપાત્ર અસર સાથેનો કોઈ સંપૂર્ણ સ્વચાલિત નિર્ણય લેવામાં આવતો નથી. છેતરપિંડી શોધ માટે અમારું AI જોખમ-સ્કોરિંગ પ્લેટફોર્મ ઍક્સેસને અસર કરી શકે છે; તમે આવા કોઈપણ નિર્ણયની માનવ સમીક્ષાની વિનંતી કરી શકો છો.';

