  @override
  String get legalPrivacyChangesBody =>
      'અમે સમય સમય પર આ ગોપનીયતા નીતિને અપડેટ કરી શકીએ છીએ. સામગ્રીના ફેરફારો પ્રભાવમાં આવે તેના ઓછામાં ઓછા 30 દિવસ પહેલા ઇમેઇલ અને ઇન-એપ સૂચના દ્વારા સૂચિત કરવામાં આવશે. અસરકારક તારીખ પછી પ્લેટફોર્મનો સતત ઉપયોગ અપડેટેડ પોલિસીની સ્વીકૃતિ બનાવે છે.';

