  @override
  String get legalPrivacyCookiesBody =>
      'સખત જરૂરી કૂકીઝ (સત્ર વ્યવસ્થાપન, સુરક્ષા ટોકન્સ) હંમેશા સક્રિય હોય છે. કાર્યાત્મક કૂકીઝ (ભાષા પસંદગી, થીમ) પ્રથમ ઉપયોગ પર સેટ છે અને બ્રાઉઝર સેટિંગ્સમાં સાફ કરી શકાય છે. ઍનલિટિક્સ કૂકીઝ (વર્સેલ, સેન્ટ્રી) ફક્ત કૂકી બેનર દ્વારા તમારી સંમતિથી સેટ કરવામાં આવે છે. અમે જાહેરાત અથવા ક્રોસ-સાઇટ ટ્રેકિંગ કૂકીઝનો ઉપયોગ કરતા નથી.';

