  @override
  String get legalPrivacyLegalBasisBody =>
      'અમે તમારા અધિકારક્ષેત્રના આધારે નીચેના કાનૂની આધારો હેઠળ વ્યક્તિગત ડેટા પર પ્રક્રિયા કરીએ છીએ: (a) કરાર — તમે સાઇન અપ કરેલ છે તે સેવાઓ પહોંચાડવા માટે જરૂરી પ્રક્રિયા; (b) કાયદેસર રુચિઓ - છેતરપિંડી નિવારણ, પ્લેટફોર્મ સુરક્ષા, ઉત્પાદન સુધારણા; (c) સંમતિ — AI પ્રશિક્ષણ, માર્કેટિંગ ઈમેલ્સ, કૂકીઝ સખત જરૂરી છે; (d) કાનૂની જવાબદારી — લાગુ કાયદાનું પાલન. ભારત માટે, પ્રોસેસિંગ ડિજિટલ પર્સનલ ડેટા પ્રોટેક્શન એક્ટ 2023 (DPDP એક્ટ) દ્વારા સંચાલિત થાય છે. UK/EU માટે, પ્રક્રિયા UK GDPR અને EU GDPRનું પાલન કરે છે. કેન્યા માટે, પ્રોસેસિંગ ડેટા પ્રોટેક્શન એક્ટ 2019નું પાલન કરે છે. યુએસ યુઝર્સ માટે, અમે CCPA/CPRA સહિત લાગુ રાજ્ય ગોપનીયતા કાયદાઓનું પાલન કરીએ છીએ.';

