  @override
  String get legalStandardDisclaimer =>
      'અમ્બ્રેલા કાનૂની માહિતી, દસ્તાવેજની સ્પષ્ટતા, મુદ્દાની ઓળખ અને જોખમ વિશ્લેષણ પ્રદાન કરે છે. તે કાયદાકીય પેઢી નથી અને લાયસન્સ ધરાવતા એટર્નીને બદલતી નથી. તમારી પરિસ્થિતિને લગતી કાનૂની સલાહ માટે, તમારા અધિકારક્ષેત્રમાં લાયક વકીલની સલાહ લો.';

  @override
  String get legalTermsAIOutputsBody =>
      'AI આઉટપુટ મોટા ભાષાના મોડલ દ્વારા જનરેટ કરવામાં આવે છે અને તે માત્ર માહિતીના હેતુ માટે જ પ્રદાન કરવામાં આવે છે. તેઓ કાનૂની સલાહની રચના કરતા નથી, એટર્ની-ક્લાયન્ટ સંબંધ બનાવતા નથી, અને લાયક વકીલની સલાહના વિકલ્પ તરીકે તેમના પર આધાર રાખવો જોઈએ નહીં. AI આઉટપુટ અપૂર્ણ, અચોક્કસ અથવા જૂના હોઈ શકે છે. કાયદાઓ અને કેસોના સંદર્ભો સ્વતંત્ર રીતે ચકાસાયેલ હોવા જોઈએ. AI આઉટપુટ પર આધારિત કોઈપણ કાર્યવાહી માટે તમે જ જવાબદાર છો.';

  @override
  String get legalTermsAIOutputsHeading => '9. AI આઉટપુટની પ્રકૃતિ';

  @override
  String get legalTermsAccountBody =>
      'તમારે ચોક્કસ અને સંપૂર્ણ નોંધણી માહિતી પ્રદાન કરવી જોઈએ અને તેને અપડેટ રાખવી જોઈએ. તમારા ઓળખપત્રોની ગોપનીયતા જાળવવા અને તમારા એકાઉન્ટ હેઠળની તમામ પ્રવૃત્તિ માટે તમે જવાબદાર છો. તમારે અમને support@odaflow.com પર કોઈપણ અનધિકૃત ઍક્સેસ વિશે તરત જ સૂચિત કરવું આવશ્યક છે. અમે એવા એકાઉન્ટ્સને અક્ષમ કરવાનો અધિકાર અનામત રાખીએ છીએ જે આ શરતોનું ઉલ્લંઘન કરે છે અથવા અમને વ્યાજબી રીતે ચેડાં થયાની શંકા છે.';

  @override
  String get legalTermsAccountHeading => '3. એકાઉન્ટ રજીસ્ટ્રેશન';

  @override
  String get legalTermsAgreementBody =>
      'ખાતું બનાવીને અથવા કોઈપણ અમ્બ્રેલા સેવાનો ઉપયોગ કરીને, તમે આ શરતોથી બંધાયેલા રહેવા માટે સંમત થાઓ છો. જો તમે કાનૂની પેઢી, કંપની અથવા અન્ય કાનૂની એન્ટિટી વતી પ્લેટફોર્મનો ઉપયોગ કરી રહ્યાં છો, તો તમે પ્રતિનિધિત્વ કરો છો કે તમારી પાસે તે એન્ટિટીને બાંધવાની સત્તા છે. જો તમે આ શરતો સ્વીકારતા નથી, તો તમારે પ્લેટફોર્મનો ઉપયોગ કરવો જોઈએ નહીં. વપરાશકર્તાઓ ઓછામાં ઓછા 18 વર્ષના હોવા જોઈએ.';

  @override
