  @override
  String get legalTermsChangesBody =>
      'અમે સમયાંતરે આ શરતોને અપડેટ કરી શકીએ છીએ. સામગ્રીના ફેરફારો પ્રભાવમાં આવે તેના ઓછામાં ઓછા 30 દિવસ પહેલા ઇમેઇલ અને ઇન-એપ સૂચના દ્વારા સૂચિત કરવામાં આવશે. અસરકારક તારીખ પછી સતત ઉપયોગ સ્વીકૃતિની રચના કરે છે.';

  @override
