  @override
  String get legalTermsConfidentialityBody =>
      'અમે તમારી સામગ્રી અને બાબતના ડેટાને ગોપનીય ગણીએ છીએ અને અમારી ગોપનીયતા નીતિમાં વર્ણવ્યા મુજબ અથવા કાયદા દ્વારા આવશ્યકતા સિવાય તેને તૃતીય પક્ષોને જાહેર કરીશું નહીં. વકીલ વપરાશકર્તાઓએ ખાતરી કરવી આવશ્યક છે કે ગ્રાહક-ગોપનીય સંચાર લાગુ વ્યાવસાયિક વિશેષાધિકાર નિયમોનું પાલન કરે છે. અમારી સિસ્ટમ્સ ભાડૂતના ડેટાને અલગ કરવા માટે આર્કિટેક્ટ છે.';

