  @override
  String get legalTermsDefinitionsBody =>
      '\"પ્લેટફોર્મ\" નો અર્થ umbrella.okaylegal.ai અને તમામ સંકળાયેલ એપ્લિકેશન્સ, API અને સેવાઓ છે. \"કન્ઝ્યુમર યુઝર\" નો અર્થ એ છે કે પોતાની કાનૂની પરિસ્થિતિને સમજવા માટે પ્લેટફોર્મનો ઉપયોગ કરતી કુદરતી વ્યક્તિ. \"વકીલ વપરાશકર્તા\" એટલે વકીલ OS સુવિધાઓનો ઉપયોગ કરીને લાઇસન્સ પ્રાપ્ત કાનૂની વ્યાવસાયિક. \"ભાડૂત\" નો અર્થ એ છે કે ફર્મ સબ્સ્ક્રિપ્શન ધરાવતી કાયદાકીય પેઢી અથવા સંસ્થા. \"AI આઉટપુટ\" નો અર્થ છે અમ્બ્રેલાની AI સિસ્ટમ્સ દ્વારા જનરેટ કરાયેલ કોઈપણ ટેક્સ્ટ, વિશ્લેષણ, ડ્રાફ્ટ અથવા ભલામણ. \"મેટર\" નો અર્થ વકીલ OS દ્વારા સંચાલિત કાનૂની કેસ અથવા વ્યવહાર. \"DVTech Ventures\" અથવા \"we\" નો અર્થ થાય છે પ્લેટફોર્મના ઓપરેટર.';

  @override
  String get legalTermsDefinitionsHeading => '2. વ્યાખ્યાઓ';

  @override
  String get legalTermsDescription =>
      'આ શરતો તમારા અમ્બ્રેલાના ઉપયોગને નિયંત્રિત કરે છે — DVTech વેન્ચર્સ દ્વારા સંચાલિત AI-નેટિવ કાનૂની પ્લેટફોર્મ. પ્લેટફોર્મના કોઈપણ ભાગનો ઉપયોગ કરતા પહેલા કૃપા કરીને તેને કાળજીપૂર્વક વાંચો.';

  @override
  String get legalTermsDisputeBody =>
      'ભારતના વપરાશકર્તાઓ: આ શરતો ભારતના કાયદા દ્વારા સંચાલિત છે; બેંગલુરુમાં બેઠેલા આર્બિટ્રેશન એન્ડ કોન્સિલિયેશન એક્ટ 1996 હેઠળ બંધનકર્તા આર્બિટ્રેશન દ્વારા વિવાદોનો ઉકેલ લાવવામાં આવશે. યુનાઇટેડ સ્ટેટ્સના વપરાશકર્તાઓ: ડેલવેરમાં બેઠેલા AAA કોમર્શિયલ આર્બિટ્રેશન નિયમો હેઠળ બંધનકર્તા આર્બિટ્રેશન દ્વારા વિવાદોનો ઉકેલ લાવવામાં આવશે; વર્ગ ક્રિયા માફી લાગુ પડે છે. કેન્યા વપરાશકર્તાઓ: આ શરતો કેન્યાના કાયદા દ્વારા સંચાલિત છે; વિવાદોનો ઉકેલ નૈરોબી સેન્ટર ફોર ઇન્ટરનેશનલ આર્બિટ્રેશન (NCIA) નિયમો હેઠળ કરવામાં આવશે. યુનાઇટેડ કિંગડમ વપરાશકર્તાઓ: આ શરતો અંગ્રેજી કાયદા દ્વારા સંચાલિત છે; વિવાદો ઇંગ્લેન્ડ અને વેલ્સની અદાલતોના વિશિષ્ટ અધિકારક્ષેત્રમાં સબમિટ કરવામાં આવશે. તમામ કેસોમાં, તમને સક્ષમ અદાલત પાસેથી તાત્કાલિક આદેશાત્મક રાહત મેળવવાથી કંઈપણ અટકાવતું નથી.';

  @override
  String get legalTermsDisputeHeading =>
      '18. વિવાદનું નિરાકરણ અને સંચાલન કાયદો';

  @override
  String get legalTermsIPContentBody =>
      'તમે પ્લેટફોર્મ પર સબમિટ કરો છો તે તમામ સામગ્રીની માલિકી તમે જાળવી રાખો છો. સામગ્રી સબમિટ કરીને તમે DVTech વેન્ચર્સને ફક્ત સેવાઓ પહોંચાડવા માટે તમારી સામગ્રીને પ્રક્રિયા કરવા, સ્ટોર કરવા અને પ્રદર્શિત કરવા માટે વિશ્વવ્યાપી, રોયલ્ટી-મુક્ત, બિન-વિશિષ્ટ લાઇસન્સ આપો છો. જ્યાં સુધી તમે ડેટા અને એઆઈ સંમતિ નીતિ હેઠળ પસંદ ન કરો ત્યાં સુધી આ લાઇસન્સ AI તાલીમ સુધી વિસ્તરતું નથી.';

  @override
  String get legalTermsIPHeading => '12. બૌદ્ધિક સંપત્તિ';

  @override
  String get legalTermsIPPlatformBody =>
      'DVTech Ventures અમ્બ્રેલા પ્લેટફોર્મ, બ્રાન્ડ, અંતર્ગત AI મોડલ્સ અને ટેક્નોલોજીના તમામ હકો ધરાવે છે. તમને તમારા સબ્સ્ક્રિપ્શનની અવધિ માટે પ્લેટફોર્મનો ઉપયોગ કરવા માટે મર્યાદિત, બિન-વિશિષ્ટ, બિન-તબદીલીપાત્ર લાઇસન્સ આપવામાં આવે છે.';

  @override
  String get legalTermsIndemnityBody =>
      'તમે હાનિકારક DVTech વેન્ચર્સ અને તેના અધિકારીઓ, નિર્દેશકો, કર્મચારીઓ અને એજન્ટોને કોઈપણ દાવાઓ, નુકસાની, નુકસાન અને ખર્ચ (વાજબી કાનૂની ફી સહિત) થી અને તેની વિરુદ્ધમાં નુકસાનની ભરપાઈ કરવા, બચાવ કરવા અને પકડી રાખવા માટે સંમત થાઓ છો: (a) આ શરતોના ઉલ્લંઘનમાં પ્લેટફોર્મનો તમારો ઉપયોગ; (b) કોઈપણ લાગુ કાયદાનું તમારું ઉલ્લંઘન; (c) તમે સબમિટ કરો છો તે સામગ્રી જે તૃતીય પક્ષના અધિકારોનું ઉલ્લંઘન કરે છે; (d) કાનૂની સલાહ અથવા સેવાઓ તમે પ્લેટફોર્મનો ઉપયોગ કરીને તમારા ગ્રાહકોને પ્રદાન કરો છો.';

  @override
