  @override
  String get legalTermsPermittedUseBody =>
      'તમે પ્લેટફોર્મનો ઉપયોગ આ માટે કરી શકો છો: વ્યક્તિગત અથવા વ્યાવસાયિક ઉપયોગ માટે AI-જનરેટેડ કાનૂની માહિતી મેળવવા; કાનૂની બાબતો, ગ્રાહકો, બિલિંગ અને દસ્તાવેજોનું સંચાલન કરો (વકીલ OS); લાઇસન્સ પ્રાપ્ત વકીલો સાથે જોડાવા માટે વકીલ બજારને ઍક્સેસ કરો; અને અમારા દસ્તાવેજીકૃત API દ્વારા પ્લેટફોર્મને તમારી સિસ્ટમ સાથે એકીકૃત કરો.';

  @override
  String get legalTermsPermittedUseHeading => '4. ઉપયોગની પરવાનગી';

  @override
  String get legalTermsProhibitedUseBody =>
      'તમારે: (a) વકીલ, ન્યાયાધીશ અથવા સરકારી અધિકારીનો ઢોંગ ન કરવો જોઈએ; (b) વકીલની સમીક્ષા વિના તૃતીય પક્ષોને ઔપચારિક કાનૂની સલાહ તરીકે AI આઉટપુટનો ઉપયોગ કરો; (c) ગેરકાનૂની, બદનક્ષીપૂર્ણ અથવા કપટપૂર્ણ સામગ્રી સબમિટ કરો; (d) અંતર્ગત AI મોડેલો અથવા તાલીમ ડેટાને રિવર્સ-એન્જિનિયર, સ્ક્રેપ અથવા કાઢવાનો પ્રયાસ કરો; (e) લેખિત સંમતિ વિના પ્લેટફોર્મ પર પુનઃવેચાણ અથવા સબલાઈસન્સ ઍક્સેસ; (f) ડેટા સંરક્ષણ, ગ્રાહક સુરક્ષા અને કાનૂની વ્યવસાય નિયમો સહિત લાગુ કાયદાનું ઉલ્લંઘન કરતી કોઈપણ રીતે પ્લેટફોર્મનો ઉપયોગ કરો; (g) તૃતીય-પક્ષના બૌદ્ધિક સંપદા અધિકારોનું ઉલ્લંઘન કરતી સામગ્રી સબમિટ કરો.';

  @override
  String get legalTermsProhibitedUseHeading => '5. પ્રતિબંધિત ઉપયોગ';

  @override
  String get legalTermsRefundBody =>
      'તમે એકાઉન્ટ સેટિંગ્સમાંથી કોઈપણ સમયે તમારું સબ્સ્ક્રિપ્શન રદ કરી શકો છો. વર્તમાન બિલિંગ અવધિના અંતે રદ કરવાની અસર થાય છે; ન વપરાયેલ સમય માટે કોઈ આંશિક રિફંડ આપવામાં આવતું નથી. જો તમને લાગે કે તમારી પાસેથી ભૂલથી શુલ્ક લેવામાં આવ્યો છે, તો ચાર્જ થયાના 30 દિવસની અંદર support@odaflow.com નો સંપર્ક કરો. અમે સમીક્ષા કરીશું અને, જો યોગ્ય હોય તો, અમારા વિવેકબુદ્ધિ મુજબ પ્રો-રેટા રિફંડ જારી કરીશું.';

  @override
  String get legalTermsRefundHeading => '8. રિફંડ અને કેન્સલેશન';

  @override
  String get legalTermsSeverabilityBody =>
      'જો આ શરતોની કોઈપણ જોગવાઈ લાગુ ન થઈ શકે તેવી જણાય છે, તો બાકીની જોગવાઈઓ સંપૂર્ણ બળમાં ચાલુ રહે છે. કોઈપણ અધિકારનો અમલ કરવામાં અમારી નિષ્ફળતા એ અધિકારની માફી નથી. આ શરતો, ગોપનીયતા નીતિ અને ડેટા અને AI સંમતિ નીતિ સાથે મળીને, પ્લેટફોર્મ સંબંધિત તમારી અને DVTech વેન્ચર્સ વચ્ચેના સમગ્ર કરારની રચના કરે છે.';

  @override
  String get legalTermsSeverabilityHeading => '19. સામાન્ય';

  @override
  String get legalTermsSubscriptionBody =>
      'ચૂકવેલ યોજનાઓનું બિલ માસિક અથવા વાર્ષિક ચક્ર પર અગાઉથી ચૂકવવામાં આવે છે. ચેકઆઉટ વખતે કિંમતો તમારા સ્થાનિક ચલણમાં પ્રદર્શિત થાય છે અને તેમાં લાગુ કરનો સમાવેશ થઈ શકે છે. સબ્સ્ક્રિપ્શન્સ દરેક બિલિંગ અવધિના અંતે સ્વતઃ-નવીકરણ થાય છે સિવાય કે તમે નવીકરણની તારીખ પહેલાં રદ કરો. ચૂકવણી કરવામાં નિષ્ફળતા સસ્પેન્શન અથવા ઍક્સેસની સમાપ્તિમાં પરિણમી શકે છે.';

  @override
