  @override
  String get legalTermsTitle => 'સેવાની શરતો';

  @override
  String get legalTermsTrialBody =>
      'સાઇન-અપ પર નિર્દિષ્ટ કર્યા મુજબ નવા એકાઉન્ટ્સ માટે મફત અજમાયશ ઉપલબ્ધ છે. અજમાયશ અવધિના અંતે, તમારું એકાઉન્ટ આપમેળે લાગુ દરે ચૂકવેલ સબ્સ્ક્રિપ્શનમાં રૂપાંતરિત થશે સિવાય કે તમે અજમાયશ સમાપ્ત થાય તે પહેલાં રદ ન કરો. અમે કોઈપણ સમયે ટ્રાયલ ઑફર્સને સંશોધિત કરવાનો અથવા બંધ કરવાનો અધિકાર અનામત રાખીએ છીએ.';

  @override
