  @override
  String get legalTermsWarrantiesBody =>
      'અમે ખાતરી આપીએ છીએ કે: (a) અમે વાજબી કુશળતા અને કાળજી સાથે પ્લેટફોર્મ પ્રદાન કરીશું; (b) અમે વ્યાપારી રીતે વાજબી સુરક્ષા પ્રથાઓ જાળવીશું. કાયદા દ્વારા મંજૂર થયેલ સંપૂર્ણ હદ સુધી, પ્લેટફોર્મ ચોક્કસ હેતુ, બિન-ઉલ્લંઘન અથવા અવિરત ઉપલબ્ધતા માટે યોગ્યતાની વોરંટી વિના \"જેમ છે તેમ\" પ્રદાન કરવામાં આવે છે. અમે AI આઉટપુટની ચોકસાઈ, સંપૂર્ણતા અથવા ચલણની બાંયધરી આપતા નથી.';

